# Break My Fix finding 1, generated by Tracefix: days_in_month returns a wrong value.
# Property (docstring): The number of days equals the Gregorian calendar's count for every valid month and year, including all century years such as 1900, 2100, 2200, 2300.
# Quote: Return the number of days in `month` (1-12) of `year`.
# Run it with pytest: it fails for as long as the code breaks this property.

import calendar

from billing.calendar import days_in_month


def test_break_my_fix_1() -> None:
    year = 2200
    month = 2
    # The property applies to this input: 1 <= year <= 9999 and 1 <= month <= 12
    result = days_in_month(year=year, month=month)
    assert result == (calendar.monthrange(year, month)[1])
